function orientCameraToObjective(){const target=objectiveTarget();if(!target?.pos)return false;const dx=target.pos.x-px,dz=target.pos.z-pz,dy=(target.pos.y||1.2)-1.15;camYaw=deg(Math.atan2(-dx,-dz));camPitch=clamp(22+dy*8,12,44);toast('Cámara orientada al objetivo.',900);return true}
function updateCameraGuide(){if(!cameraGuide||!gameStarted||!activeRoute){if(cameraGuide)cameraGuide.style.display='none';return}const target=objectiveTarget();if(!target?.pos){cameraGuide.style.display='none';return}const dist=Math.hypot(target.pos.x-px,target.pos.z-pz);const camComp=document.querySelector('#cameraRig pc-camera')?.component;let msg='';if(camComp){const screen=new Vec3();camComp.worldToScreen(new Vec3(target.pos.x,target.pos.y,target.pos.z),screen);const visible=screen.z>0&&screen.x>=0&&screen.x<=innerWidth&&screen.y>=0&&screen.y<=innerHeight;if(visible)msg=`<strong>OBJETIVO</strong> · ${target.label} a la vista · ${dist.toFixed(1)} m`;else{let dir='girá la cámara';if(screen.z>0){if(screen.x<0)dir='girá a la izquierda';else if(screen.x>innerWidth)dir='girá a la derecha';else if(screen.y<0)dir='bajá la cámara';else dir='subí la cámara'}else{const goal=deg(Math.atan2(-(target.pos.x-px),-(target.pos.z-pz)));const delta=((goal-camYaw+540)%360)-180;dir=delta>0?'girá a la izquierda':'girá a la derecha'}msg=`<strong>OBJETIVO</strong> · ${target.label} · ${dir} · Q centrar cámara`}}else msg=`<strong>OBJETIVO</strong> · ${target.label} · Q centrar cámara`;cameraGuide.innerHTML=msg;cameraGuide.style.display='block'}
function chooseInteractable(){if(modalLayer.style.display==='grid'||intro.style.display==='grid')return null;const yaw=rad(camYaw),fx=-Math.sin(yaw),fz=-Math.cos(yaw);let best=null,bestScore=Infinity;for(const it of getInteractables()){const pos=it.position(),dx=pos.x-px,dz=pos.z-pz,dist=Math.hypot(dx,dz);if(dist>it.radius||dist<.001||!lineClearTo(pos,it.id==='door'))continue;const dot=(dx/dist)*fx+(dz/dist)*fz;if(dot<-.30)continue;const score=dist+(1-dot)*.72;if(score<bestScore){best=it;bestScore=score}}return best}
function interact(){const target=currentInteractable||chooseInteractable();if(!target){const msg=tutorialStep>=19?(routeCopy(tutorialStep)?.[1]||'Seguí el objetivo del epílogo.'):tutorialStep===14?'Recorrido de taller completado.':'Seguí la indicación actual.';toast(msg,1500);return}target.interact()}
function updateInteractionUI(){currentInteractable=chooseInteractable();const camComp=document.querySelector('#cameraRig pc-camera')?.component;if(!currentInteractable){promptEl.style.display='none';const target=objectiveTarget();if(!camComp||!target?.pos){interactMarker.style.display='none';return}const screen=new Vec3();camComp.worldToScreen(new Vec3(target.pos.x,target.pos.y,target.pos.z),screen);if(screen.z>0&&screen.x>=0&&screen.x<=innerWidth&&screen.y>=0&&screen.y<=innerHeight){interactMarker.style.display='block';interactMarker.classList.add('active');interactMarker.style.left=screen.x+'px';interactMarker.style.top=(screen.y-(innerWidth<720?34:26))+'px'}else interactMarker.style.display='none';return}promptEl.textContent='E · '+currentInteractable.prompt();promptEl.style.display='block';if(!camComp){interactMarker.style.display='none';return}const p=currentInteractable.position(),screen=new Vec3();camComp.worldToScreen(new Vec3(p.x,p.y,p.z),screen);if(screen.z>0&&screen.x>=0&&screen.x<=innerWidth&&screen.y>=0&&screen.y<=innerHeight){interactMarker.style.display='block';interactMarker.classList.add('active');interactMarker.style.left=screen.x+'px';interactMarker.style.top=(screen.y-(innerWidth<720?34:26))+'px'}else interactMarker.style.display='none'}

